      pbSwapDone[1] = false;
      pbSwapDone[2] = false;
      pbSwapDone[3] = false;
      SERVER_ITEM_SendStackableUsagePackets(pUnit, ".\\ITEMS\\ItemMode.cpp", 0xe24);
      pInventory = pUnit->pInventory;
      pInventorySaved = pInventory;
